/**
 * Main server entry point
 * Initializes Express app, database connections, and scheduled tasks
 * 
 * IDEA: Add clustering support for production using Node.js cluster module
 * to utilize all CPU cores
 */

require('dotenv').config();
const app = require('./src/app');
const { connectDatabase } = require('./src/config/database');
const { connectRedis } = require('./src/config/redis');
const { startScraperCron } = require('./src/services/scraperService');
const logger = require('./src/utils/logger');

const PORT = process.env.PORT || 5000;

/**
 * Graceful shutdown handler
 * Ensures all connections are properly closed before shutting down
 */
const gracefulShutdown = (signal) => {
  logger.info(`Received ${signal}. Starting graceful shutdown...`);
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
};

const startServer = async () => {
  try {
    // Connect to MongoDB
    await connectDatabase();
    logger.info('✅ MongoDB connected successfully');

    // Connect to Redis cache
    await connectRedis();
    logger.info('✅ Redis connected successfully');

    // Start the HTTP server
    const server = app.listen(PORT, () => {
      logger.info(`✅ Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
    });

    // Start scheduled scraping every 6 hours
    // IDEA: Make this configurable via admin panel
    startScraperCron();
    logger.info('✅ Scraper cron job started');

    // Handle graceful shutdown signals
    process.on('SIGTERM', gracefulShutdown);
    process.on('SIGINT', gracefulShutdown);

    // Handle unhandled promise rejections
    process.on('unhandledRejection', (err) => {
      logger.error('Unhandled Promise Rejection:', err);
      server.close(() => process.exit(1));
    });

  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
};

startServer();
