/**
 * MongoDB database configuration
 * Uses Mongoose ODM for schema-based modeling
 * 
 * IDEA: Implement read replicas for scaling read-heavy operations
 * IDEA: Add connection pooling configuration for production
 */

const mongoose = require('mongoose');
const logger = require('../utils/logger');

/**
 * Connect to MongoDB with retry logic
 * @param {number} retries - Number of connection retry attempts
 */
const connectDatabase = async (retries = 5) => {
  const options = {
    useNewUrlParser: true,
    useUnifiedTopology: true,
    maxPoolSize: 10, // Maximum connection pool size
    serverSelectionTimeoutMS: 5000,
    socketTimeoutMS: 45000,
    bufferMaxEntries: 0,
  };

  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      await mongoose.connect(process.env.MONGODB_URI, options);

      // Monitor connection events
      mongoose.connection.on('error', (err) => {
        logger.error('MongoDB connection error:', err);
      });

      mongoose.connection.on('disconnected', () => {
        logger.warn('MongoDB disconnected. Attempting reconnection...');
      });

      return;
    } catch (error) {
      logger.error(`MongoDB connection attempt ${attempt} failed:`, error.message);

      if (attempt === retries) {
        throw new Error('Failed to connect to MongoDB after maximum retries');
      }

      // Exponential backoff: wait 2^attempt seconds before retrying
      await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 1000));
    }
  }
};

module.exports = { connectDatabase };
